begin;

create or replace function public.refresh_contribution_intelligence_v1(
  target_project uuid
) returns jsonb
language plpgsql
security definer
set search_path=public,private,auth,extensions
as $$declare caller uuid:=auth.uid();model public.contribution_reputation_models%rowtype;window_name text;window_start timestamptz;window_end timestamptz:=now();batch uuid;rolling_batch uuid;lifetime_batch uuid;refreshed integer:=0;inserted_count integer:=0;begin if caller is null then raise insufficient_privilege using message='Authentication is required.';end if;if not private.has_project_role(target_project,array['owner','admin'])then raise insufficient_privilege using message='Owner or admin access is required.';end if;select * into model from public.contribution_reputation_models where project_id=target_project and status='active' order by effective_from desc nulls last,created_at desc limit 1;if not found then raise exception 'No active contribution reputation model exists.';end if;insert into public.contribution_anomaly_signals(project_id,user_id,contribution_id,signal_type,severity,confidence,signal_key,evidence)select target_project,c.user_id,min(c.id::text)::uuid,'reused_evidence','high',1,'DN-ANOM-EVID-'||encode(digest(target_project::text||':'||c.user_id::text||':'||e.content_hash,'sha256'),'hex'),jsonb_build_object('content_hash',e.content_hash,'contribution_count',count(distinct c.id),'contribution_ids',jsonb_agg(distinct c.id))from public.contribution_evidence e join public.contribution_ledger c on c.id=e.contribution_id where c.project_id=target_project and e.content_hash is not null group by c.user_id,e.content_hash having count(distinct c.id)>1 on conflict(signal_key)do update set confidence=excluded.confidence,evidence=excluded.evidence,detected_at=now()where public.contribution_anomaly_signals.status='open';insert into public.contribution_anomaly_signals(project_id,user_id,contribution_id,signal_type,severity,confidence,signal_key,evidence)select target_project,c.user_id,c.id,'self_review','critical',1,'DN-ANOM-SELF-'||replace(r.id::text,'-',''),jsonb_build_object('review_id',r.id,'review_stage',r.review_stage,'decision',r.decision)from public.contribution_reviews r join public.contribution_ledger c on c.id=r.contribution_id where c.project_id=target_project and r.reviewer_id=c.user_id on conflict(signal_key)do nothing;insert into public.contribution_anomaly_signals(project_id,user_id,signal_type,severity,confidence,signal_key,evidence)select target_project,c.user_id,'burst_certification','medium',least(1,count(*)::numeric/12),'DN-ANOM-BURST-'||encode(digest(target_project::text||':'||c.user_id::text||':'||date_trunc('hour',c.certified_at)::text,'sha256'),'hex'),jsonb_build_object('hour',date_trunc('hour',c.certified_at),'certified_count',count(*),'note','Review signal only;open signals do not reduce reputation.')from public.contribution_ledger c where c.project_id=target_project and c.certification_state='certified' and c.certified_at is not null group by c.user_id,date_trunc('hour',c.certified_at)having count(*)>=8 on conflict(signal_key)do update set confidence=excluded.confidence,evidence=excluded.evidence,detected_at=now()where public.contribution_anomaly_signals.status='open';foreach window_name in array array['rolling_90','lifetime'] loop batch:=gen_random_uuid();window_start:=case when window_name='rolling_90' then window_end - interval '90 days' else null end;with base as(select sp.user_id,sp.lifecycle_stage,sp.reputation_opt_in,coalesce(pref.ranking_opt_in,true)as ranking_opt_in,coalesce(pref.squad_opt_in,false)as squad_opt_in,count(distinct c.id)filter(where c.certification_state='certified' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start))::integer as certified_count,coalesce(sum(s.contribution_score)filter(where c.certification_state='certified' and s.status='final' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start)),0)::numeric as impact_raw,coalesce(avg(s.quality_rating)filter(where c.certification_state='certified' and s.status='final' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start)),0)::numeric * 100 as quality_score,coalesce(avg(private.jsonb_ratio_01(s.dimension_ratings,'documentation_mentoring'))filter(where c.certification_state='certified' and s.status='final' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start)),0)::numeric * 100 as collaboration_score,coalesce(avg(private.jsonb_ratio_01(s.dimension_ratings,'governance_process'))filter(where c.certification_state='certified' and s.status='final' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start)),0)::numeric * 100 as governance_score,coalesce(avg(private.jsonb_ratio_01(s.dimension_ratings,'datanest_ai_learning'))filter(where c.certification_state='certified' and s.status='final' and(window_start is null or coalesce(c.certified_at,c.created_at)>=window_start)),0)::numeric * 100 as knowledge_score from public.stakeholder_profiles sp left join public.datanest_user_preferences pref on pref.user_id=sp.user_id left join public.contribution_ledger c on c.project_id=sp.project_id and c.user_id=sp.user_id left join public.contribution_scores s on s.contribution_id=c.id and s.status='final' where sp.project_id=target_project and sp.status='active' group by sp.user_id,sp.lifecycle_stage,sp.reputation_opt_in,pref.ranking_opt_in,pref.squad_opt_in),reviews as(select sp.user_id,count(r.id)filter(where r.decision='approved' and(window_start is null or r.created_at>=window_start))::integer as approved_reviews from public.stakeholder_profiles sp left join public.contribution_reviews r on r.project_id=sp.project_id and r.reviewer_id=sp.user_id where sp.project_id=target_project and sp.status='active' group by sp.user_id),signals as(select sp.user_id,coalesce(sum(private.anomaly_severity_weight(a.severity)*a.confidence)filter(where a.status in('open','confirmed')),0)::numeric as anomaly_points,coalesce(sum(private.anomaly_severity_weight(a.severity)*a.confidence)filter(where a.status='confirmed'),0)::numeric as confirmed_penalty,count(a.id)filter(where a.status='confirmed' and a.severity in('high','critical'))::integer as confirmed_high_count from public.stakeholder_profiles sp left join public.contribution_anomaly_signals a on a.project_id=sp.project_id and a.user_id=sp.user_id where sp.project_id=target_project and sp.status='active' group by sp.user_id),normalized as(select b.*,coalesce(r.approved_reviews,0)as approved_reviews,least(100,coalesce(g.anomaly_points,0))as anomaly_score,greatest(0,100-least(100,coalesce(g.confirmed_penalty,0)))as trust_score,coalesce(g.confirmed_high_count,0)as confirmed_high_count,case when max(b.impact_raw)over()>0 then round((b.impact_raw/max(b.impact_raw)over())*100,6)else 0 end as impact_score from base b left join reviews r on r.user_id=b.user_id left join signals g on g.user_id=b.user_id),scored as(select n.*,round(model.impact_weight*n.impact_score + model.quality_weight*n.quality_score + model.collaboration_weight*n.collaboration_score + model.governance_weight*n.governance_score + model.knowledge_weight*n.knowledge_score,6)as aggregate_score,(n.reputation_opt_in and n.ranking_opt_in and n.certified_count>=model.minimum_certified_for_rank and n.confirmed_high_count=0)as eligible,array_remove(array[ case when not n.reputation_opt_in then 'project_reputation_disabled' end,case when not n.ranking_opt_in then 'ranking_opt_out' end,case when n.certified_count<model.minimum_certified_for_rank then 'insufficient_certified_contributions' end,case when n.confirmed_high_count>0 then 'confirmed_high_risk_signal' end ]::text[],null)as reasons from normalized n),ranked as(select s.*,case when s.eligible then row_number()over(order by case when s.eligible then s.aggregate_score end desc nulls last,case when s.eligible then s.trust_score end desc nulls last,case when s.eligible then s.certified_count end desc nulls last,s.user_id)::integer else null end as calculated_rank from scored s)insert into public.reputation_snapshots(project_id,user_id,window_type,period_start,period_end,aggregate_score,dimensions,rank,model_version,batch_id,trust_score,anomaly_score,eligible_for_ranking,exclusion_reasons,certified_contributions,approved_reviews,frozen_at)select target_project,ranked.user_id,window_name,window_start,window_end,ranked.aggregate_score,jsonb_build_object('impact',round(ranked.impact_score,6),'quality',round(ranked.quality_score,6),'collaboration_mentoring',round(ranked.collaboration_score,6),'governance',round(ranked.governance_score,6),'reusable_knowledge',round(ranked.knowledge_score,6),'weights',jsonb_build_object('impact',model.impact_weight,'quality',model.quality_weight,'collaboration_mentoring',model.collaboration_weight,'governance',model.governance_weight,'reusable_knowledge',model.knowledge_weight),'open_signals_are_not_reputation_penalties',true),ranked.calculated_rank,model.model_version,batch,ranked.trust_score,ranked.anomaly_score,ranked.eligible,ranked.reasons,ranked.certified_count,ranked.approved_reviews,now()from ranked;get diagnostics inserted_count=row_count;refreshed:=refreshed + inserted_count;if window_name='rolling_90' then rolling_batch:=batch;update public.n0nymous_squad_memberships set status='expired',expired_at=now()where project_id=target_project and status='active';with candidates as(select rs.*,row_number()over(order by rs.aggregate_score desc,rs.trust_score desc,rs.certified_contributions desc,rs.user_id)::integer as squad_rank from public.reputation_snapshots rs join public.datanest_user_preferences pref on pref.user_id=rs.user_id where rs.project_id=target_project and rs.batch_id=batch and rs.window_type='rolling_90' and rs.eligible_for_ranking and rs.certified_contributions>=model.minimum_certified_for_squad and pref.squad_opt_in)insert into public.n0nymous_squad_memberships(project_id,batch_id,snapshot_id,user_id,member_code,rank,aggregate_score,trust_score,status)select target_project,batch,candidates.id,candidates.user_id,'N0-'||upper(substr(encode(digest(target_project::text||':'||candidates.user_id::text,'sha256'),'hex'),1,8)),candidates.squad_rank,candidates.aggregate_score,candidates.trust_score,'active' from candidates where candidates.squad_rank<=10;else lifetime_batch:=batch;insert into public.stakeholder_progression_recommendations(project_id,user_id,current_stage,recommended_stage,basis_snapshot_id,rationale)select target_project,sp.user_id,sp.lifecycle_stage,case when sp.lifecycle_stage in('accepted_user','active_stakeholder')and rs.certified_contributions>=1 and rs.trust_score>=90 then 'verified_contributor' when sp.lifecycle_stage='verified_contributor' and rs.aggregate_score>=model.trusted_score_threshold and rs.certified_contributions>=model.trusted_minimum_certified and rs.trust_score>=90 then 'trusted_contributor' when sp.lifecycle_stage='trusted_contributor' and rs.aggregate_score>=model.reviewer_score_threshold and rs.certified_contributions>=model.reviewer_minimum_certified and rs.approved_reviews>=model.reviewer_minimum_reviews and rs.trust_score>=95 then 'reviewer' else null end,rs.id,jsonb_build_object('aggregate_score',rs.aggregate_score,'trust_score',rs.trust_score,'certified_contributions',rs.certified_contributions,'approved_reviews',rs.approved_reviews,'model_version',model.model_version,'automatic_privilege_change',false)from public.reputation_snapshots rs join public.stakeholder_profiles sp on sp.project_id=rs.project_id and sp.user_id=rs.user_id where rs.project_id=target_project and rs.batch_id=batch and rs.window_type='lifetime' and rs.eligible_for_ranking and((sp.lifecycle_stage in('accepted_user','active_stakeholder')and rs.certified_contributions>=1 and rs.trust_score>=90)or(sp.lifecycle_stage='verified_contributor' and rs.aggregate_score>=model.trusted_score_threshold and rs.certified_contributions>=model.trusted_minimum_certified and rs.trust_score>=90)or(sp.lifecycle_stage='trusted_contributor' and rs.aggregate_score>=model.reviewer_score_threshold and rs.certified_contributions>=model.reviewer_minimum_certified and rs.approved_reviews>=model.reviewer_minimum_reviews and rs.trust_score>=95))on conflict do nothing;end if;end loop;insert into public.events(project_id,event_type,actor,payload)values(target_project,'CONTRIBUTION_INTELLIGENCE_REFRESHED',coalesce(auth.jwt()->>'email',caller::text),jsonb_build_object('model_version',model.model_version,'rolling_batch',rolling_batch,'lifetime_batch',lifetime_batch,'snapshot_rows',refreshed,'open_signals_are_not_reputation_penalties',true,'squad_grants_admin',false));return jsonb_build_object('model_version',model.model_version,'rolling_batch',rolling_batch,'lifetime_batch',lifetime_batch,'snapshot_rows',refreshed);end;$$;


commit;
